static int rtl8153_enable(struct r8152 *tp)
{
	int ret;

	if (test_bit(RTL8152_UNPLUG, &tp->flags))
		return -ENODEV;

	set_tx_qlen(tp);
	ret = rtl_set_eee_plus(tp);
	if (ret < 0)
		goto out;
	ret = r8153_set_rx_early_timeout(tp);
	if (ret < 0)
		goto out;
	ret = r8153_set_rx_early_size(tp);
	if (ret < 0)
		goto out;

	ret = rtl_set_ifg(tp, rtl8152_get_speed(tp));
	if (ret < 0)
		goto out;

	switch (tp->version) {
	case RTL_VER_14:
		ret = ocp_word_clr_bits(tp, MCU_TYPE_USB, USB_FW_TASK,
					FC_PATCH_TASK);
		if (ret < 0)
			goto out;
		usleep_range(1000, 2000);
		ret = ocp_word_set_bits(tp, MCU_TYPE_USB, USB_FW_TASK,
					FC_PATCH_TASK);
		if (ret < 0)
			goto out;
		break;
	default:
		break;
	}

	ret = rtl_enable(tp);

out:
	return ret;
}
